	var options controllerOptions
	for _, opt := range opts {
		opt(&options)
	}
	options.SetDefaults()

	ctx, cancel := context.WithCancel(context.Background())
	return &Controller{
		store:            NewStore(),
		serverKeepAlive:  options.serverKeepAlive,
		serverTTL:        apidefaults.ServerAnnounceTTL,
