+func TestControllerSSHServerHeartbeatPeerAddr(t *testing.T) {
+	for _, tt := range []struct {
+		name, addr, peer, want string
+	}{
+		{"ipv6 wildcard", "[::]:3022", "192.0.2.5:50000", "192.0.2.5:3022"},
+		{"ipv4 wildcard", "0.0.0.0:3022", "[2001:db8::5]:50000", "[2001:db8::5]:3022"},
+		{"loopback", "127.0.0.1:3022", "192.0.2.5:50000", "192.0.2.5:3022"},
+		{"empty host", ":3022", "192.0.2.5:50000", "192.0.2.5:3022"},
+		{"routable", "198.51.100.3:3022", "192.0.2.5:50000", "198.51.100.3:3022"},
+		{"no peer", "[::]:3022", "", "[::]:3022"},
+		{"malformed address", "bad-address", "192.0.2.5:50000", "bad-address"},
+	} {
+		t.Run(tt.name, func(t *testing.T) {
+			auth := &fakeAuth{}
+			controller := NewController(auth)
+			defer controller.Close()
+			upstream, downstream := client.InventoryControlStreamPipe(client.ICSPipePeerAddr(tt.peer))
+			defer downstream.Close()
+			handle := newUpstreamHandle(upstream, proto.UpstreamInventoryHello{
+				ServerID: "test-server",
+				Services: []types.SystemRole{types.RoleNode},
+			})
+			server := &types.ServerV2{Metadata: types.Metadata{Name: "test-server"}}
+			server.SetAddr(tt.addr)
+			require.NoError(t, controller.handleSSHServerHB(handle, server))
+			require.Equal(t, tt.want, auth.lastAddr)
+		})
+	}
+}
